function hasOwn(record, key) {
  return Object.prototype.hasOwnProperty.call(record, key);
}

function normalizeInteger(value) {
  if (typeof value === 'bigint') {
    return value;
  }

  if (typeof value === 'number' && Number.isInteger(value)) {
    return BigInt(value);
  }

  throw new TypeError('Bidict values must be integers.');
}

class InverseView {
  constructor(owner) {
    this.owner = owner;
  }

  get(value) {
    return this.owner.inverseGet(value);
  }
}

export class Bidict {
  constructor(initialEntries = undefined) {
    this.forward = Object.create(null);
    this.inverse = Object.create(null);
    this.order = [];
    this.inv = new InverseView(this);

    if (initialEntries !== undefined) {
      this.load(initialEntries);
    }
  }

  load(initialEntries) {
    if (Array.isArray(initialEntries)) {
      for (const [key, value] of initialEntries) {
        this.set(key, value);
      }
      return this;
    }

    for (const key of Object.keys(initialEntries)) {
      this.set(key, initialEntries[key]);
    }

    return this;
  }

  set(key, value) {
    const normalizedKey = String(key);
    const normalizedValue = normalizeInteger(value);
    const inverseKey = normalizedValue.toString();

    if (
      hasOwn(this.inverse, inverseKey) &&
      this.inverse[inverseKey] !== normalizedKey
    ) {
      throw new ValueDuplicationError(normalizedValue);
    }

    if (hasOwn(this.forward, normalizedKey)) {
      const previousValue = this.forward[normalizedKey];

      if (previousValue === normalizedValue) {
        return this;
      }

      delete this.inverse[previousValue.toString()];
      this.forward[normalizedKey] = normalizedValue;
      this.inverse[inverseKey] = normalizedKey;
      return this;
    }

    this.order.push(normalizedKey);
    this.forward[normalizedKey] = normalizedValue;
    this.inverse[inverseKey] = normalizedKey;
    return this;
  }

  copy() {
    return new Bidict(this.entries());
  }

  entries() {
    return this.order.map((key) => [key, this.forward[key]]);
  }

  inverseGet(value) {
    const normalizedValue = normalizeInteger(value);
    const inverseKey = normalizedValue.toString();

    if (!hasOwn(this.inverse, inverseKey)) {
      throw new KeyError(normalizedValue);
    }

    return this.inverse[inverseKey];
  }

  toString() {
    return bidictRepr(this.entries());
  }
}

import { bidict } from './lib/bidict.mjs';
import { ParserExit, parseArguments } from './lib/cli_parser.mjs';

function writeText(streamName, text) {
  process[streamName].write(text);
}

function main(argv, programPath) {
  const args = parseArguments(argv, programPath);
  const b1 = bidict([
    [args.k1, args.v1],
    [args.k2, args.v2],
  ]);
  const b2 = b1.copy();

  writeText('stdout', `${b2}\n`);

  b1.set('new', 999);
  writeText('stdout', `${b1}\n`);
  writeText('stdout', `${b2}\n`);

  const result = b2.inv[args.v1];
  writeText('stdout', `${String(result)}\n`);
}

try {
  main(process.argv.slice(2), process.argv[1]);
} catch (error) {
  if (error instanceof ParserExit) {
    writeText(error.stream, error.text);
    process.exitCode = error.code;
  } else {
    throw error;
  }
}

