import { ARGUMENT_DEFINITIONS, HELP_ARGUMENT, buildHelp, buildUsage } from './definitions.mjs';

function isOptionLike(token) {
  return typeof token === 'string' && token.startsWith('-') && token !== '-';
}

function isIntegerToken(token) {
  return typeof token === 'string' && /^[+-]?\d(?:_?\d)*$/.test(token);
}

function parseIntegerToken(token) {
  return BigInt(token.replaceAll('_', ''));
}

function buildParserState() {
  const values = Object.create(null);

  for (const definition of ARGUMENT_DEFINITIONS) {
    values[definition.destination] = undefined;
  }

  return values;
}

function matchLongOption(optionToken) {
  const allLongOptions = [
    HELP_ARGUMENT.longOption,
    ...ARGUMENT_DEFINITIONS.map((definition) => definition.longOption),
  ];

  if (allLongOptions.includes(optionToken)) {
    return optionToken;
  }

  const matches = allLongOptions.filter((candidate) => candidate.startsWith(optionToken));
  if (matches.length === 1) {
    return matches[0];
  }

  if (matches.length > 1) {
    return { ambiguous: true, matches };
  }

  return null;
}

function writeAndExit(stream, message, exitCode) {
  stream.write(message);
  process.exit(exitCode);
}

function writeHelpAndExit(programName, stdout) {
  writeAndExit(stdout, buildHelp(programName), 0);
}

function writeErrorAndExit(programName, stderr, message) {
  writeAndExit(stderr, `${buildUsage(programName)}\n${programName}: error: ${message}\n`, 2);
}

function consumeAttachedValue(rawToken) {
  const equalsIndex = rawToken.indexOf('=');
  if (equalsIndex === -1) {
    return null;
  }

  return {
    optionToken: rawToken.slice(0, equalsIndex),
    attachedValue: rawToken.slice(equalsIndex + 1),
  };
}

function parseValue(definition, rawValue, programName, stderr) {
  if (definition.type === 'int') {
    if (!isIntegerToken(rawValue)) {
      writeErrorAndExit(
        programName,
        stderr,
        `argument ${definition.longOption}: invalid int value: '${rawValue}'`,
      );
    }

    return parseIntegerToken(rawValue);
  }

  return rawValue;
}

function takeSeparatedValue(definition, argv, currentIndex, programName, stderr) {
  const rawValue = argv[currentIndex + 1];

  if (rawValue === undefined) {
    writeErrorAndExit(programName, stderr, `argument ${definition.longOption}: expected one argument`);
  }

  if (definition.type === 'string') {
    if (isOptionLike(rawValue)) {
      writeErrorAndExit(programName, stderr, `argument ${definition.longOption}: expected one argument`);
    }

    return { rawValue, nextIndex: currentIndex + 1 };
  }

  if (isOptionLike(rawValue) && !isIntegerToken(rawValue)) {
    writeErrorAndExit(programName, stderr, `argument ${definition.longOption}: expected one argument`);
  }

  return { rawValue, nextIndex: currentIndex + 1 };
}

function handleLongOption(rawToken, argv, index, values, extras, programName, stdout, stderr) {
  const attached = consumeAttachedValue(rawToken);
  const optionToken = attached ? attached.optionToken : rawToken;
  const matchedOption = matchLongOption(optionToken);

  if (matchedOption && typeof matchedOption === 'object' && matchedOption.ambiguous) {
    writeErrorAndExit(
      programName,
      stderr,
      `ambiguous option: ${optionToken} could match ${matchedOption.matches.join(', ')}`,
    );
  }

  if (matchedOption === HELP_ARGUMENT.longOption) {
    if (attached) {
      writeErrorAndExit(
        programName,
        stderr,
        `argument ${HELP_ARGUMENT.shortOption}/${HELP_ARGUMENT.longOption}: ignored explicit argument '${attached.attachedValue}'`,
      );
    }

    writeHelpAndExit(programName, stdout);
  }

  if (matchedOption === null) {
    extras.push(rawToken);
    return index;
  }

  const definition = ARGUMENT_DEFINITIONS.find(
    (candidate) => candidate.longOption === matchedOption,
  );

  let rawValue;
  let nextIndex = index;

  if (attached) {
    rawValue = attached.attachedValue;
  } else {
    const consumed = takeSeparatedValue(definition, argv, index, programName, stderr);
    rawValue = consumed.rawValue;
    nextIndex = consumed.nextIndex;
  }

  values[definition.destination] = parseValue(definition, rawValue, programName, stderr);
  return nextIndex;
}

function reportMissingRequired(values, programName, stderr) {
  const missing = ARGUMENT_DEFINITIONS
    .filter((definition) => definition.required && values[definition.destination] === undefined)
    .map((definition) => definition.longOption);

  if (missing.length > 0) {
    writeErrorAndExit(
      programName,
      stderr,
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }
}

function reportExtrasIfAny(extras, programName, stderr) {
  if (extras.length > 0) {
    writeErrorAndExit(programName, stderr, `unrecognized arguments: ${extras.join(' ')}`);
  }
}

export function parseCommandLine(argv, programName, io = { stdout: process.stdout, stderr: process.stderr }) {
  const values = buildParserState();
  const extras = [];
  let endOfOptions = false;

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (endOfOptions) {
      extras.push(token);
      continue;
    }

    if (token === '--') {
      extras.push(token);
      endOfOptions = true;
      continue;
    }

    if (token === HELP_ARGUMENT.shortOption) {
      writeHelpAndExit(programName, io.stdout);
    }

    if (token.startsWith('--') && token.length > 2) {
      index = handleLongOption(token, argv, index, values, extras, programName, io.stdout, io.stderr);
      continue;
    }

    extras.push(token);
  }

  reportMissingRequired(values, programName, io.stderr);
  reportExtrasIfAny(extras, programName, io.stderr);
  return values;
}

function toHex(value, width) {
  return value.toString(16).padStart(width, '0');
}

function escapeCharacter(codePoint) {
  if (codePoint <= 0xff) {
    return `\\x${toHex(codePoint, 2)}`;
  }

  if (codePoint <= 0xffff) {
    return `\\u${toHex(codePoint, 4)}`;
  }

  return `\\U${toHex(codePoint, 8)}`;
}

function chooseQuote(value) {
  if (value.includes("'") && !value.includes('"')) {
    return '"';
  }

  return "'";
}

export function pythonStringRepr(value) {
  const quote = chooseQuote(value);
  let result = quote;

  for (const character of value) {
    const codePoint = character.codePointAt(0);

    if (character === quote || character === '\\') {
      result += `\\${character}`;
      continue;
    }

    if (character === '\n') {
      result += '\\n';
      continue;
    }

    if (character === '\r') {
      result += '\\r';
      continue;
    }

    if (character === '\t') {
      result += '\\t';
      continue;
    }

    if (character === '\b') {
      result += '\\b';
      continue;
    }

    if (character === '\f') {
      result += '\\f';
      continue;
    }

    if (character === '\v') {
      result += '\\v';
      continue;
    }

    if (codePoint < 0x20 || codePoint === 0x7f) {
      result += escapeCharacter(codePoint);
      continue;
    }

    result += character;
  }

  return `${result}${quote}`;
}

export function bidictRepr(entries) {
  if (entries.length === 0) {
    return 'bidict()';
  }

  const inner = entries
    .map(([key, value]) => `${pythonStringRepr(key)}: ${value.toString()}`)
    .join(', ');

  return `bidict({${inner}})`;
}

